/** One workbench, one bounded run, one combined TXT. */
public class RecorderActivity extends Activity {
 TextView state,server;final Handler handler=new Handler(Looper.getMainLooper());String serverStatus="";boolean authBusy;
 public void onCreate(Bundle saved){super.onCreate(saved);LogStore.init(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);int pad=(int)(20*getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);box.setBackgroundColor(0xff0b1013);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(box);setContentView(scroll);if(Build.VERSION.SDK_INT>=35)getWindow().getDecorView().setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars());box.setPadding(pad,bars.top+pad,pad,bars.bottom+pad);return i;});
  text(box,"CELIKOM · 0.3.23",26);text(box,"Комплексная проверка",21);text(box,"Определение песни → сервер → автозамена → пауза и перемотка → возврат оригинала. Один общий TXT. Доступ к уведомлениям не нужен.",16);
  button(box,"Начать комплексную проверку",this::begin);state=text(box,"",16);
  button(box,"Открыть Яндекс Музыку",()->{Intent i=getPackageManager().getLaunchIntentForPackage(LogStore.PKG);if(i!=null)startActivity(i);else toast("Яндекс Музыка не найдена");});
  button(box,"Включить автозамену до конца проверки",this::trial);
  button(box,"Вернуть оригинал сейчас",()->{ProbeService p=ProbeService.instance;if(p!=null&&p.replacement!=null)p.replacement.returnOriginal();});
  button(box,"Подтвердить найденную версию (резерв)",()->{ProbeService p=ProbeService.instance;if(p==null||p.replacement==null||p.replacement.trackId==null){toast("Сначала дождись определения песни");return;}ReplacementEngine e=p.replacement;PlaybackSource s=p.current;if(s==null||!s.key.equals(e.identityKey)){toast("Песня уже изменилась");return;}final String key=s.key,id=e.trackId;new AlertDialog.Builder(this).setTitle("Это нужная версия песни?").setMessage(s.title+" — "+s.artist+"\nID: "+id+"\n\nЭто резервное совпадение по названию, исполнителю и длительности. Подтверди только если подходит именно эта версия.").setNegativeButton("Отмена",null).setPositiveButton("Подтвердить",(d,w)->{if(p.current!=null&&p.current.key.equals(key)&&id.equals(e.trackId))e.confirm();}).show();});
  server=text(box,"",16);button(box,"Войти в аккаунт CELIKOM",this::login);button(box,"Проверить сервер и доступ",this::checkServer);
  button(box,"Активировать доступ CELIKOM",()->{if(authBusy)return;new AlertDialog.Builder(this).setTitle("Активировать CELIKOM?").setMessage("Сервер проверит подписку. Если пробный период ещё не запускался, начнётся предусмотренный аккаунтом пробный период. Это тот же аккаунт, что в расширении.").setNegativeButton("Отмена",null).setPositiveButton("Активировать",(d,w)->{authBusy=true;NativeApi.get(this).activate((j,e)->{authBusy=false;serverStatus=e==null?"Активация выполнена":error(e);checkServer();});}).show();});
  button(box,"Выйти из аккаунта CELIKOM",()->{if(authBusy)return;ProbeService p=ProbeService.instance;if(p!=null&&p.replacement!=null)p.replacement.stop("logout");authBusy=true;NativeApi.get(this).logout((j,e)->{authBusy=false;serverStatus="Выполнен выход на этом устройстве";});});
  button(box,"Обновить проверки после смены сети",()->{ProbeService p=ProbeService.instance;if(p==null||p.albumProbe==null){checkServer();return;}p.albumProbe.retry();p.replacement.suspend("owner_network_retry",0);checkServer();});
  button(box,"Остановить всё и сохранить TXT",this::export);button(box,"Остановить без экспорта",()->{ProbeService p=ProbeService.instance;if(p!=null)p.finish("owner_stop");});
  text(box,"Один сценарий проверки",20);text(box,"1. Войди в CELIKOM и начни комплексную проверку.\n2. В Яндексе включи песню, для которой у нас есть замена, например «Ау» — 10AGE, Ramil'.\n3. Открой эквалайзер из Яндекса → CELIKOM. Включи автозамену один раз. Можно включить её заранее: она дождётся песни и подключения через эквалайзер.\n4. Вернись в Яндекс: пауза → продолжить → перемотка → следующая песня. Вернись к «Ау»: замена должна включиться сама. Проверь выключенный экран и краткое отключение сети. При отключении наушников воспроизведение ставится на паузу; для продолжения нажми ▶ в Яндексе. Режим сохраняется. Если Яндекс сменит аудиосессию, CELIKOM попросит открыть эквалайзер повторно.\n5. Сохрани один TXT и пришли вместе с коротким описанием, что услышал.\n\nПовторно отправлять три ссылки на уже проверенную песню не нужно.",16);
  button(box,"Прежние аудиопроверки",()->startActivity(new Intent().setClassName(this,"pro.celikom.nativeprobe.MainActivity").putExtra("legacy_tools",true)));
  text(box,"Установка и данные",20);text(box,"Используются обычные интерфейсы Android. Нет чтения уведомлений, SMS, микрофона и управления экраном. Пароль CELIKOM отправляется только на сервер CELIKOM; в Яндекс входить здесь не нужно. Пароль не сохраняется, сессия шифруется ключом Android. Отчёт остаётся на телефоне до твоего экспорта.\n\nРешение об установке принимает Google Play Protect. Эта сборка не отключает и не обходит защиту. При блокировке сохрани текст предупреждения; в 0.3.18 владелец подтвердил установку с включённой защитой; новая сборка требует отдельной проверки.",14);
  receive(getIntent());handler.post(update);
 }
 TextView text(LinearLayout b,String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xffebeef0);t.setPadding(0,12,0,16);t.setTextIsSelectable(true);b.addView(t);return t;}
 void button(LinearLayout b,String s,Runnable r){Button v=new Button(this);v.setText(s);v.setAllCaps(false);b.addView(v,new LinearLayout.LayoutParams(-1,-2));v.setOnClickListener(w->r.run());}
 EditText input(LinearLayout box,String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setInputType(type);e.setSingleLine(true);e.setSaveEnabled(false);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);box.addView(e);return e;}
 void trial(){ProbeService p=ProbeService.instance;if(p==null||!LogStore.active){toast("Сначала начни комплексную проверку");return;}if(!NativeApi.get(this).signedIn()){LogStore.log("replacement_trial_unavailable",LogStore.map("reason","login_required","shownToOwner",true));new AlertDialog.Builder(this).setTitle("Для замены нужен вход в CELIKOM").setMessage("Прежний тест использовал местный тестовый звук. Настоящая версия песни загружается с сервера CELIKOM и требует твой аккаунт — тот же, что в расширении. Сейчас замена ещё не запускалась.").setNegativeButton("Отмена",null).setPositiveButton("Войти в CELIKOM",(d,w)->login()).show();return;}ReplacementEngine e=p.replacement;PlaybackSource source=p.current;if(e==null)return;if(source==null||e.trackId==null||!source.key.equals(e.identityKey)){new AlertDialog.Builder(this).setTitle("Включить ожидание Яндекса?").setMessage("После определения песни автозамена подключится сама. Для управления звуком сначала открой эквалайзер из Яндекса → CELIKOM один раз. Повторно включать режим после этого не нужно. Резервное совпадение потребует подтверждения.").setNegativeButton("Отмена",null).setPositiveButton("Включить",(d,w)->p.beginTrial()).show();return;}final String key=source.key,id=e.trackId;boolean fallback=!"ALBUM".equals(e.method);String message=(fallback?"Резервное совпадение по названию, исполнителю и длительности:\n"+source.title+" — "+source.artist+"\nID: "+id+"\nПодтверди, что это нужная песня. Доступность самой замены дополнительно проверит сервер.\n\n":"")+"Оригинал приглушается только после подготовки замены. Пауза и перемотка остаются в Яндексе. Автозамена действует на следующие песни до остановки общей проверки (не более 12 минут). Резервные совпадения для новых песен требуют подтверждения.";new AlertDialog.Builder(this).setTitle(fallback?"Подтвердить песню и проверить замену?":"Проверить замену звука?").setMessage(message).setNegativeButton("Отмена",null).setPositiveButton("Запустить",(d,w)->{if(p.current==null||!p.current.key.equals(key)||!id.equals(e.trackId)){toast("Песня изменилась — запусти проверку заново");return;}if(fallback)e.confirm();p.beginTrial();if(!e.armed())new AlertDialog.Builder(this).setTitle("Замена не запущена").setMessage(e.status).setPositiveButton("Понятно",null).show();}).show();}
 void login(){if(authBusy)return;LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(32,12,32,12);EditText email=input(form,"Почта CELIKOM",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),password=input(form,"Пароль CELIKOM",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Вход в CELIKOM").setView(form).setNegativeButton("Отмена",null).setPositiveButton("Войти",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String address=email.getText().toString().trim(),pass=password.getText().toString();if(address.length()>254||pass.length()>128||address.isEmpty()||pass.isEmpty()){toast("Введи почту и пароль CELIKOM");return;}authBusy=true;password.setText("");dialog.dismiss();serverStatus="Выполняется вход…";NativeApi.get(this).login(address,pass,(j,e)->{authBusy=false;if(e!=null){serverStatus=error(e);new AlertDialog.Builder(this).setTitle("Не удалось войти в CELIKOM").setMessage(serverStatus).setPositiveButton("Понятно",null).show();return;}if(j.optBoolean("verification_required")){serverStatus="Нужен код подтверждения из почты";verify(address);}else{serverStatus="Вход выполнен";resetLookup();checkServer();}});}));dialog.show();}
 void verify(String address){EditText code=new EditText(this);code.setHint("Код из письма");code.setInputType(InputType.TYPE_CLASS_NUMBER);code.setSaveEnabled(false);new AlertDialog.Builder(this).setTitle("Подтвердить почту CELIKOM").setView(code).setNegativeButton("Отмена",null).setPositiveButton("Подтвердить",(d,w)->{if(authBusy)return;authBusy=true;NativeApi.get(this).verify(address,code.getText().toString(),(j,e)->{authBusy=false;serverStatus=e==null?"Почта подтверждена, вход выполнен":error(e);if(e==null){resetLookup();checkServer();}});}).show();}
 void resetLookup(){ProbeService p=ProbeService.instance;if(p!=null&&p.replacement!=null){p.replacement.lookupKey=null;p.replacement.descriptor=null;}}
 void checkServer(){if(authBusy)return;authBusy=true;serverStatus="Проверяем сервер…";NativeApi.get(this).check((j,e)->{authBusy=false;if(e!=null){serverStatus=error(e);return;}JSONObject entitlement=j.optJSONObject("entitlement");serverStatus="Сервер работает · "+(!j.optBoolean("signedIn")?"нужен вход":entitlement!=null&&entitlement.optBoolean("allowed")?"доступ активен":"нет активного доступа — проверь активацию");});}
 String error(String e){return "CELIKOM: "+ReplacementEngine.message(e);}
 final Runnable update=new Runnable(){public void run(){ProbeService p=ProbeService.instance;String now="";if(p!=null&&p.current!=null){PlaybackSource s=p.current;now="\n"+s.title+" — "+s.artist+"\n"+(s.playing?"Играет":"Пауза")+" · "+s.position/1000+" / "+s.duration/1000+" с";}state.setText(LogStore.status()+"\n"+(p==null?"Проверка не запущена":p.connectionStatus)+now+(p!=null&&p.replacement!=null?"\nID: "+(p.replacement.trackId==null?"ожидаем":p.replacement.trackId)+" · "+p.replacement.method+"\n"+p.replacement.status:"")+(p!=null&&p.albumProbe!=null?"\n"+p.albumProbe.status():""));server.setText((NativeApi.get(RecorderActivity.this).signedIn()?"Аккаунт CELIKOM подключён":"Вход в CELIKOM не выполнен")+(serverStatus.isEmpty()?"":"\n"+serverStatus));handler.postDelayed(this,500);}};
 void begin(){if(LogStore.active){toast("Комплексная проверка уже идёт");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);return;}startRun();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==10)startRun();}
 void startRun(){if(LogStore.file.exists()&&LogStore.file.length()>0)new AlertDialog.Builder(this).setTitle("Начать новую проверку?").setMessage("Предыдущий несохранённый отчёт будет заменён. Сохранённые TXT останутся.").setPositiveButton("Начать",(d,w)->launch()).setNegativeButton("Отмена",null).show();else launch();}
 void launch(){try{startForegroundService(new Intent(this,ProbeService.class));toast("Проверка запущена");}catch(RuntimeException e){toast("Android не разрешил запустить проверку");}}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);receive(i);}
 void receive(Intent i){if(i==null||!Intent.ACTION_SEND.equals(i.getAction()))return;CharSequence text=i.getCharSequenceExtra(Intent.EXTRA_TEXT);List<Object> links=ShareLinks.parse(text==null?"":text.toString());if(LogStore.active&&!links.isEmpty()){LogStore.log("share_reference",LogStore.map("links",links));ProbeService p=ProbeService.instance;if(p!=null&&p.albumProbe!=null)p.albumProbe.reference(links);toast("Ссылка добавлена в общий отчёт");}setIntent(new Intent(this,RecorderActivity.class));}
 void export(){if(LogStore.file==null||!LogStore.file.exists()||LogStore.file.length()==0){toast("Отчёт пока пуст");return;}ProbeService p=ProbeService.instance;if(p!=null)p.finish("export_requested");else LogStore.end("export_requested");try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"CELIKOM-combined-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date())+".txt"),20);}catch(RuntimeException e){toast("Не удалось открыть сохранение TXT");}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=20||result!=RESULT_OK||data==null||data.getData()==null)return;try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException();out.write("CELIKOM COMBINED 0.3.23\nOne run: identity, backend, replacement and restoration. No credentials or audio bytes in this report.\n\n".getBytes(StandardCharsets.UTF_8));synchronized(LogStore.class){try(InputStream in=new FileInputStream(LogStore.file)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}toast("Общий TXT сохранён");}catch(Exception e){toast("Не удалось сохранить TXT");}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
